const INSTALL_REF_PATTERN = /^r_[A-Za-z0-9]{6,12}$/;
const INSTALL_REF_FLAG = '--ref';
const INSTALL_REF_INLINE_PREFIX = `${INSTALL_REF_FLAG}=`;

type ExtractedInstallRef = {
  installRef: string | undefined;
  remainingArgs: string[];
};

export const parseInstallRef = (value: unknown): string | undefined =>
  typeof value === 'string' && INSTALL_REF_PATTERN.test(value)
    ? value
    : undefined;

export const extractInstallRef = (args: string[]): ExtractedInstallRef => {
  let installRef: string | undefined;
  const remainingArgs: string[] = [];

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.startsWith(INSTALL_REF_INLINE_PREFIX)) {
      installRef = parseInstallRef(arg.slice(INSTALL_REF_INLINE_PREFIX.length));
      continue;
    }
    if (arg !== INSTALL_REF_FLAG) {
      remainingArgs.push(arg);
      continue;
    }
    const next = args[i + 1];
    if (next === undefined || next.startsWith('--')) {
      continue;
    }
    installRef = parseInstallRef(next);
    i++;
  }

  return { installRef, remainingArgs };
};
